{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "The closest analogue, orientin (luteolin 8-C-glucoside), showed only low brain levels after intravenous administration in rats and was judged impermeable due to high polarity; the query shares the same luteolin aglycone, C-glucoside, and B-ring catechol, so this directly supports inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Isovitexin (apigenin 6-C-glucoside), which shares the 6-C-glucosylation of the query, was detected in rat brain after i.v. dosing at ~15 ng/mL and labeled permeable; however, it lacks the 3'-hydroxyl present in the query, making it less polar and limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C04"],
      "claim": "Cyanidin-3-O-glucoside, a polar anthocyanin glycoside, was detected in brain within seconds after i.v. injection, showing that some glycosides can achieve rapid brain exposure; but its cationic flavylium structure and lower similarity reduce its weight for the neutral luteolin C-glucoside query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Hyperoside, a quercetin 3-O-galactoside, was detected in rat brain after oral administration, providing additional evidence that flavonoid glycosides can cross the BBB; its O-glycoside linkage and lower similarity make it less decisive than the closest C-glucoside analogue.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the closest experimental analogue, orientin, shows poor brain penetration after IV administration, and the query shares the same highly polar luteolin C-glucoside scaffold. Although some related flavonoid glycosides are detected in brain, they are less similar or less polar, so inadequate CNS access is more likely.",
  "evidence_gaps": [
    "No direct isoorientin brain/plasma pharmacokinetic data.",
    "Conflicting results between the closest analogues orientin (fail) and isovitexin (pass).",
    "No quantitative unbound brain concentrations or transporter contribution data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

